  ('PSY 101', 'Introduction to Psychology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Political Science', '200 Level', 'first', 2, 'The Science of Psychology: History of Psychology Research methods in Psychology Fields of Psychology and other Disciplines. Biological Basis of Human Development.', '["The Science of Psychology: History of Psychology", "Research methods in Psychology", "Fields of Psychology and other Disciplines", "Biological Basis of Human Development"]'::jsonb, 'Department of Psychology handbook'),
